import { createHash } from "node:crypto";
import { validateAddonName } from "./addon.js";
import { RELEASE_CANDIDATE_BOUNDARIES, RELEASE_CANDIDATE_CONTRACT_WARNING } from "./release-candidate-result.js";
import { MAX_SECRET_SCAN_BYTES, RELEASE_METADATA_KEYS, RELEASE_SENSITIVE_MATERIAL_RULES } from "./release-readiness.js";
const CANONICAL_VECTOR_VALUE = [
    "1.0",
    [[
            "content",
            "content/dota_addons/demo/maps/demo.vmap",
            7,
            "a".repeat(64)
        ]]
];
export const REMOTE_RELEASE_CANDIDATE_POLICY = Object.freeze({
    schemaVersion: "1.0",
    maxSecretScanBytes: MAX_SECRET_SCAN_BYTES,
    releaseMetadataKeys: RELEASE_METADATA_KEYS,
    sensitiveMaterialRules: RELEASE_SENSITIVE_MATERIAL_RULES,
    boundaries: RELEASE_CANDIDATE_BOUNDARIES,
    precreationArtifactStatus: "not-reached",
    contractEvidenceWarning: RELEASE_CANDIDATE_CONTRACT_WARNING,
    canonicalVector: Object.freeze({
        value: CANONICAL_VECTOR_VALUE,
        sha256: createHash("sha256").update(JSON.stringify(CANONICAL_VECTOR_VALUE), "utf8").digest("hex")
    })
});
export function buildRemoteReleaseCandidateScript(input) {
    const validation = validateAddonName(input.addonName);
    if (!validation.ok)
        throw new Error("INVALID_ADDON_NAME");
    if (typeof input.dotaRoot !== "string" || input.dotaRoot.trim().length === 0) {
        throw new Error("REMOTE_DOTA_ROOT_REQUIRED");
    }
    if (input.dotaRoot.includes("\0") || /[\r\n]/.test(input.dotaRoot)) {
        throw new Error("REMOTE_DOTA_ROOT_INVALID");
    }
    const metadataKeys = RELEASE_METADATA_KEYS.map(quotePowerShell).join(", ");
    const boundaries = Object.entries(RELEASE_CANDIDATE_BOUNDARIES)
        .map(([key, value]) => `${key} = $${value ? "true" : "false"}`)
        .join("; ");
    const canonicalJson = JSON.stringify(CANONICAL_VECTOR_VALUE);
    const sensitiveMaterialRulesJson = JSON.stringify(RELEASE_SENSITIVE_MATERIAL_RULES);
    return [
        "$ErrorActionPreference = 'Stop'",
        "$ProgressPreference = 'SilentlyContinue'",
        "$InformationPreference = 'SilentlyContinue'",
        `$SchemaVersion = '1.0'`,
        `$PrecreationArtifactStatus = 'not-reached'`,
        `$ContractEvidenceWarning = ${quotePowerShell(RELEASE_CANDIDATE_CONTRACT_WARNING)}`,
        `$MaxSecretScanBytes = ${MAX_SECRET_SCAN_BYTES}`,
        `$ReleaseMetadataKeys = @(${metadataKeys})`,
        `$SensitiveMaterialRulesJson = ${quotePowerShell(sensitiveMaterialRulesJson)}`,
        "$SensitiveMaterialRules = @($SensitiveMaterialRulesJson | ConvertFrom-Json)",
        `$CanonicalVectorJson = ${quotePowerShell(canonicalJson)}`,
        `$CanonicalVectorSha256 = '${REMOTE_RELEASE_CANDIDATE_POLICY.canonicalVector.sha256}'`,
        "$CanonicalVectorEntries = @([ordered]@{ schemaVersion = '1.0'; root = 'content'; path = 'content/dota_addons/demo/maps/demo.vmap'; bytes = 7; sha256 = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' })",
        `$DotaRootInput = ${quotePowerShell(input.dotaRoot)}`,
        `$AddonName = ${quotePowerShell(input.addonName)}`,
        "function Get-HexDigest([byte[]]$Bytes) { return -join ($Bytes | ForEach-Object { $_.ToString('x2') }) }",
        "function Get-TextSha256([string]$Text) { $sha = [Security.Cryptography.SHA256]::Create(); try { return Get-HexDigest ($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text))) } finally { $sha.Dispose() } }",
        "function Get-FileSha256([string]$Path) { $stream = [IO.FileStream]::new($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read); $sha = [Security.Cryptography.SHA256]::Create(); try { return Get-HexDigest ($sha.ComputeHash($stream)) } finally { $sha.Dispose(); $stream.Dispose() } }",
        "function Copy-FileStreamed([string]$Source, [string]$Destination) { $sourceStream = [IO.FileStream]::new($Source, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read); $destinationStream = [IO.FileStream]::new($Destination, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None); try { $buffer = [byte[]]::new(131072); while (($read = $sourceStream.Read($buffer, 0, $buffer.Length)) -gt 0) { $destinationStream.Write($buffer, 0, $read) }; $destinationStream.Flush($true) } finally { $destinationStream.Dispose(); $sourceStream.Dispose() } }",
        "function Test-ContainedPath([string]$Root, [string]$Path) { $rootFull = [IO.Path]::GetFullPath($Root).TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar); $pathFull = [IO.Path]::GetFullPath($Path); return $pathFull.StartsWith($rootFull + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase) }",
        "function Test-PathsDisjoint([string]$Left, [string]$Right) { $leftFull = [IO.Path]::GetFullPath($Left).TrimEnd('\\', '/'); $rightFull = [IO.Path]::GetFullPath($Right).TrimEnd('\\', '/'); return -not ($leftFull.Equals($rightFull, [StringComparison]::OrdinalIgnoreCase) -or (Test-ContainedPath $leftFull $rightFull) -or (Test-ContainedPath $rightFull $leftFull)) }",
        "function Get-Identity([string]$RootKind, [string]$Relative) { return ($RootKind + '/dota_addons/' + $AddonName + $(if ($Relative.Length -gt 0) { '/' + $Relative } else { '' })) }",
        "function Add-Blocker([string]$Code, [string]$Category, [string]$Path = '', [string]$Field = '') { $item = [ordered]@{ code = $Code; category = $Category; disposition = 'blocker' }; if ($Path.Length -gt 0) { $item.path = $Path }; if ($Field.Length -gt 0) { $item.field = $Field }; $script:result.blockers += $item }",
        "function Stop-ReleaseCandidate([string]$Code, [string]$Category, [string]$Path = '', [string]$Field = '') { Add-Blocker $Code $Category $Path $Field; throw 'REMOTE_LIFECYCLE_ABORTED' }",
        "function Get-SafeRelativePath([string]$Root, [string]$Path) { if (-not (Test-ContainedPath $Root $Path)) { Stop-ReleaseCandidate 'SOURCE_ENTRY_OUTSIDE_ROOT' 'source-isolation' }; return $Path.Substring($Root.TrimEnd('\\', '/').Length).TrimStart('\\', '/').Replace('\\', '/') }",
        "function Get-WindowsFileIdentity([string]$Path, [bool]$Required = $true) { $output = @(& fsutil.exe file queryFileID $Path 2>$null); $match = [regex]::Match(($output -join ' '), '0x([0-9A-Fa-f]{32})'); if ($LASTEXITCODE -ne 0 -or -not $match.Success) { if ($Required) { Stop-ReleaseCandidate 'WINDOWS_FILE_IDENTITY_REQUIRED' 'identity' }; return $null }; return $match.Groups[1].Value.ToLowerInvariant() }",
        "function Get-WindowsVolumeIdentity([string]$Path, [bool]$Required = $true) { try { $root = [IO.Path]::GetPathRoot([IO.Path]::GetFullPath($Path)); $output = @(& mountvol.exe $root /L 2>$null); $match = [regex]::Match(($output -join ' '), 'Volume\\{([0-9A-Fa-f-]{36})\\}', [Text.RegularExpressions.RegexOptions]::IgnoreCase); if ($LASTEXITCODE -ne 0 -or -not $match.Success) { throw 'WINDOWS_VOLUME_IDENTITY_UNAVAILABLE' }; return $match.Groups[1].Value.ToLowerInvariant() } catch { if ($Required) { Stop-ReleaseCandidate 'WINDOWS_FILE_IDENTITY_REQUIRED' 'volume-identity' }; return $null } }",
        "function Assert-NoReparseAncestry([string]$Path, [string]$Code) { $full = [IO.Path]::GetFullPath($Path); $root = [IO.Path]::GetPathRoot($full); $current = $(if ($full.Equals($root, [StringComparison]::OrdinalIgnoreCase)) { $root } else { $full.TrimEnd('\\', '/') }); while ($true) { $item = Get-Item -LiteralPath $current -Force; if (-not $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate $Code 'isolation' }; if ($current.Equals($root, [StringComparison]::OrdinalIgnoreCase)) { break }; $parent = [IO.Path]::GetDirectoryName($current); if ([string]::IsNullOrEmpty($parent)) { Stop-ReleaseCandidate $Code 'isolation' }; $current = $(if ($parent.Equals($root, [StringComparison]::OrdinalIgnoreCase)) { $root } else { $parent.TrimEnd('\\', '/') }) } }",
        "function Get-WindowsIdentityChain([string]$Path, [string]$Code = 'WINDOWS_FILE_IDENTITY_REQUIRED', [bool]$Required = $true) { try { $full = [IO.Path]::GetFullPath($Path); $root = [IO.Path]::GetPathRoot($full); $volumeIdentity = Get-WindowsVolumeIdentity $root $false; if ($null -eq $volumeIdentity) { throw 'UNAVAILABLE_VOLUME_IDENTITY' }; $current = $(if ($full.Equals($root, [StringComparison]::OrdinalIgnoreCase)) { $root } else { $full.TrimEnd('\\', '/') }); $chain = @(); while ($true) { $item = Get-Item -LiteralPath $current -Force; if (-not $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'UNSAFE_IDENTITY_CHAIN' }; $fileIdentity = Get-WindowsFileIdentity $current $false; if ($null -eq $fileIdentity) { throw 'UNAVAILABLE_IDENTITY_CHAIN' }; $chain += [ordered]@{ volumeIdentity = $volumeIdentity; fileIdentity = $fileIdentity }; if ($current.Equals($root, [StringComparison]::OrdinalIgnoreCase)) { break }; $parent = [IO.Path]::GetDirectoryName($current); if ([string]::IsNullOrEmpty($parent)) { throw 'INCOMPLETE_IDENTITY_CHAIN' }; $current = $(if ($parent.Equals($root, [StringComparison]::OrdinalIgnoreCase)) { $root } else { $parent.TrimEnd('\\', '/') }) }; return @($chain) } catch { if ($Required) { Stop-ReleaseCandidate $Code 'identity' }; return $null } }",
        "function Test-IdentityTupleEqual([object]$Left, [object]$Right) { return $Left.volumeIdentity.Equals($Right.volumeIdentity, [StringComparison]::Ordinal) -and $Left.fileIdentity.Equals($Right.fileIdentity, [StringComparison]::Ordinal) }",
        "function Test-IdentityChainsEqual([object[]]$Left, [object[]]$Right) { if ($null -eq $Left -or $null -eq $Right -or $Left.Count -ne $Right.Count) { return $false }; for ($index = 0; $index -lt $Left.Count; $index += 1) { if (-not (Test-IdentityTupleEqual $Left[$index] $Right[$index])) { return $false } }; return $true }",
        "function Test-IdentityChainsDisjoint([object[]]$Left, [object[]]$Right) { if ($null -eq $Left -or $null -eq $Right -or $Left.Count -eq 0 -or $Right.Count -eq 0) { return $false }; $leftRoot = $Left[0]; $rightRoot = $Right[0]; foreach ($entry in $Right) { if (Test-IdentityTupleEqual $entry $leftRoot) { return $false } }; foreach ($entry in $Left) { if (Test-IdentityTupleEqual $entry $rightRoot) { return $false } }; return $true }",
        "function New-IsolationLease([string]$parent, [string]$DotaRoot, [string]$GameRoot, [string]$ContentRoot) { Assert-NoReparseAncestry $parent 'TEMP_PARENT_NOT_ISOLATED'; Assert-NoReparseAncestry $DotaRoot 'SOURCE_ENTRY_UNSAFE'; Assert-NoReparseAncestry $GameRoot 'SOURCE_ENTRY_UNSAFE'; Assert-NoReparseAncestry $ContentRoot 'SOURCE_ENTRY_UNSAFE'; $tempChain = Get-WindowsIdentityChain $parent 'TEMP_PARENT_NOT_ISOLATED'; $dotaChain = Get-WindowsIdentityChain $DotaRoot 'SOURCE_ENTRY_UNSAFE'; $gameChain = Get-WindowsIdentityChain $GameRoot 'SOURCE_ENTRY_UNSAFE'; $contentChain = Get-WindowsIdentityChain $ContentRoot 'SOURCE_ENTRY_UNSAFE'; if (-not (Test-IdentityChainsDisjoint $tempChain $dotaChain) -or -not (Test-IdentityChainsDisjoint $tempChain $gameChain) -or -not (Test-IdentityChainsDisjoint $tempChain $contentChain)) { Stop-ReleaseCandidate 'TEMP_PARENT_NOT_ISOLATED' 'isolation' }; return [ordered]@{ tempPath = [IO.Path]::GetFullPath($parent); tempIdentity = Get-WindowsFileIdentity $parent; tempChain = $tempChain; dotaPath = [IO.Path]::GetFullPath($DotaRoot); dotaIdentity = Get-WindowsFileIdentity $DotaRoot; dotaChain = $dotaChain; gamePath = [IO.Path]::GetFullPath($GameRoot); gameIdentity = Get-WindowsFileIdentity $GameRoot; gameChain = $gameChain; contentPath = [IO.Path]::GetFullPath($ContentRoot); contentIdentity = Get-WindowsFileIdentity $ContentRoot; contentChain = $contentChain } }",
        "function Test-IsolationLease([object]$IsolationLease) { try { $tempChain = Get-WindowsIdentityChain $IsolationLease.tempPath '' $false; $dotaChain = Get-WindowsIdentityChain $IsolationLease.dotaPath '' $false; $gameChain = Get-WindowsIdentityChain $IsolationLease.gamePath '' $false; $contentChain = Get-WindowsIdentityChain $IsolationLease.contentPath '' $false; if (-not (Test-IdentityChainsEqual $tempChain $IsolationLease.tempChain) -or -not (Test-IdentityChainsEqual $dotaChain $IsolationLease.dotaChain) -or -not (Test-IdentityChainsEqual $gameChain $IsolationLease.gameChain) -or -not (Test-IdentityChainsEqual $contentChain $IsolationLease.contentChain)) { return $false }; if (-not (Test-IdentityChainsDisjoint $tempChain $dotaChain) -or -not (Test-IdentityChainsDisjoint $tempChain $gameChain) -or -not (Test-IdentityChainsDisjoint $tempChain $contentChain)) { return $false }; if (-not (Test-PathsDisjoint $IsolationLease.tempPath $IsolationLease.dotaPath) -or -not (Test-PathsDisjoint $IsolationLease.tempPath $IsolationLease.gamePath) -or -not (Test-PathsDisjoint $IsolationLease.tempPath $IsolationLease.contentPath)) { return $false }; return $true } catch { return $false } }",
        "function Test-SensitiveIdentity([string]$Relative) { foreach ($segment in $Relative.Split('/')) { foreach ($rule in $SensitiveMaterialRules) { $options = $(if ($rule.ignoreCase) { [Text.RegularExpressions.RegexOptions]::IgnoreCase } else { [Text.RegularExpressions.RegexOptions]::None }); if ([regex]::IsMatch($segment, $rule.pattern, $options)) { return $true } } }; return $false }",
        "function Assert-SafeSourceRoot([string]$DotaRoot, [string]$Root) { if (-not (Test-ContainedPath $DotaRoot $Root)) { Stop-ReleaseCandidate 'SOURCE_ENTRY_OUTSIDE_ROOT' 'source-isolation' }; $dotaFull = [IO.Path]::GetFullPath($DotaRoot).TrimEnd('\\', '/'); $current = [IO.Path]::GetFullPath($Root).TrimEnd('\\', '/'); while ($true) { $item = Get-Item -LiteralPath $current -Force; if (-not $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'SOURCE_ENTRY_UNSAFE' 'source-safety' }; if ($current.Equals($dotaFull, [StringComparison]::OrdinalIgnoreCase)) { break }; $parent = [IO.Path]::GetDirectoryName($current); if ([string]::IsNullOrEmpty($parent) -or ($parent -ne $dotaFull -and -not (Test-ContainedPath $dotaFull $parent))) { Stop-ReleaseCandidate 'SOURCE_ENTRY_OUTSIDE_ROOT' 'source-isolation' }; $current = $parent.TrimEnd('\\', '/') } }",
        "function Assert-SafeSourceAncestors([string]$Root, [string]$Path, [string]$EvidencePath = '') { $rootFull = [IO.Path]::GetFullPath($Root).TrimEnd('\\', '/'); $current = [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Path)).TrimEnd('\\', '/'); while ($true) { if ($current -ne $rootFull -and -not (Test-ContainedPath $rootFull $current)) { Stop-ReleaseCandidate 'SOURCE_ENTRY_OUTSIDE_ROOT' 'source-isolation' $EvidencePath }; $item = Get-Item -LiteralPath $current -Force; if (-not $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'SOURCE_ENTRY_UNSAFE' 'source-safety' $EvidencePath }; if ($current.Equals($rootFull, [StringComparison]::OrdinalIgnoreCase)) { break }; $current = [IO.Path]::GetDirectoryName($current).TrimEnd('\\', '/') } }",
        "function Assert-SafeSourceTree([string]$RootKind, [string]$Root) { $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase); foreach ($entry in @(Get-ChildItem -LiteralPath $Root -Recurse -Force)) { $relative = Get-SafeRelativePath $Root $entry.FullName; $identity = Get-Identity $RootKind $relative; if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'SOURCE_ENTRY_UNSAFE' 'source-safety' $identity }; if (-not ($entry.PSIsContainer -or $entry -is [IO.FileInfo])) { Stop-ReleaseCandidate 'SOURCE_ENTRY_UNSAFE' 'source-safety' $identity }; if (Test-SensitiveIdentity $relative) { Stop-ReleaseCandidate 'SOURCE_IDENTITY_SENSITIVE' 'source-identity' $identity }; if (-not $seen.Add($relative)) { Stop-ReleaseCandidate 'SOURCE_IDENTITY_COLLISION' 'source-identity' $identity } } }",
        "function Get-SourceInventory([string]$RootKind, [string]$Root) { $files = @(); $directories = @([ordered]@{ root = $RootKind; relative = ''; identity = Get-Identity $RootKind ''; sourceRoot = $Root; source = $Root; fileIdentity = Get-WindowsFileIdentity $Root }); foreach ($entry in @(Get-ChildItem -LiteralPath $Root -Recurse -Force)) { $relative = Get-SafeRelativePath $Root $entry.FullName; $identity = Get-Identity $RootKind $relative; if ($entry.PSIsContainer) { if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'SOURCE_ENTRY_UNSAFE' 'source-safety' $identity }; $directories += [ordered]@{ root = $RootKind; relative = $relative; identity = $identity; sourceRoot = $Root; source = $entry.FullName; fileIdentity = Get-WindowsFileIdentity $entry.FullName } } elseif ($entry -is [IO.FileInfo]) { Assert-SafeSourceAncestors $Root $entry.FullName $identity; $files += [ordered]@{ root = $RootKind; relative = $relative; identity = $identity; sourceRoot = $Root; source = $entry.FullName; fileIdentity = Get-WindowsFileIdentity $entry.FullName; bytes = [long]$entry.Length } } else { Stop-ReleaseCandidate 'SOURCE_ENTRY_UNSAFE' 'source-safety' $identity } }; return [ordered]@{ files = @($files); directories = @($directories) } }",
        "function Assert-SafeSourceFile([object]$File) { Assert-SafeSourceAncestors $File.sourceRoot $File.source $File.identity; $item = Get-Item -LiteralPath $File.source -Force; if (-not ($item -is [IO.FileInfo]) -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'SOURCE_ENTRY_CHANGED' 'source-safety' $File.identity }; if (-not (Test-ContainedPath $File.sourceRoot $item.FullName)) { Stop-ReleaseCandidate 'SOURCE_ENTRY_OUTSIDE_ROOT' 'source-isolation' $File.identity }; $relative = Get-SafeRelativePath $File.sourceRoot $item.FullName; if (-not $relative.Equals($File.relative, [StringComparison]::Ordinal) -or -not (Get-Identity $File.root $relative).Equals($File.identity, [StringComparison]::Ordinal) -or -not (Get-WindowsFileIdentity $File.source).Equals($File.fileIdentity, [StringComparison]::Ordinal)) { Stop-ReleaseCandidate 'SOURCE_FILE_IDENTITY_CHANGED' 'source-identity' $File.identity } }",
        "function Assert-SafeSourceDirectory([object]$Directory) { Assert-NoReparseAncestry $Directory.source 'SOURCE_ENTRY_UNSAFE'; $item = Get-Item -LiteralPath $Directory.source -Force; if (-not $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'SOURCE_CHANGED_DURING_ASSEMBLY' 'source-integrity' $Directory.identity }; $relative = $(if ($Directory.relative.Length -eq 0) { '' } else { Get-SafeRelativePath $Directory.sourceRoot $item.FullName }); if (-not $relative.Equals($Directory.relative, [StringComparison]::Ordinal) -or -not (Get-Identity $Directory.root $relative).Equals($Directory.identity, [StringComparison]::Ordinal) -or -not (Get-WindowsFileIdentity $Directory.source).Equals($Directory.fileIdentity, [StringComparison]::Ordinal)) { Stop-ReleaseCandidate 'SOURCE_CHANGED_DURING_ASSEMBLY' 'source-integrity' $Directory.identity } }",
        "function Get-InventoryTopology([object]$Inventory) { $rows = @(); foreach ($directory in $Inventory.directories) { Assert-SafeSourceDirectory $directory; $rows += ($directory.root + [char]0 + $directory.relative + [char]0 + 'directory' + [char]0 + $directory.fileIdentity) }; foreach ($file in $Inventory.files) { Assert-SafeSourceFile $file; $rows += ($file.root + [char]0 + $file.relative + [char]0 + 'file' + [char]0 + $file.fileIdentity) }; [Array]::Sort($rows, [StringComparer]::Ordinal); return ConvertTo-Json -InputObject @($rows) -Compress }",
        "function Assert-SourceTopologyStable([string]$GameRoot, [string]$ContentRoot, [string]$GameTopology, [string]$ContentTopology) { $finalGameInventory = Get-SourceInventory 'game' $GameRoot; $finalContentInventory = Get-SourceInventory 'content' $ContentRoot; if ((Get-InventoryTopology $finalGameInventory) -cne $GameTopology -or (Get-InventoryTopology $finalContentInventory) -cne $ContentTopology) { Stop-ReleaseCandidate 'SOURCE_CHANGED_DURING_ASSEMBLY' 'source-integrity' } }",
        "function Test-RequiredPath([string]$Path, [string]$Kind, [string]$Field) { if (-not (Test-Path -LiteralPath $Path)) { Add-Blocker 'REQUIRED_PATH_MISSING' 'required-structure' '' $Field; return }; $item = Get-Item -LiteralPath $Path -Force; $matches = $(if ($Kind -eq 'directory') { $item.PSIsContainer } else { -not $item.PSIsContainer }); if (-not $matches) { Add-Blocker 'REQUIRED_PATH_WRONG_KIND' 'required-structure' '' $Field } }",
        "function Test-ReleaseReadiness([string]$GameRoot, [string]$ContentRoot, [object[]]$Files) { Test-RequiredPath $GameRoot 'directory' 'game addon root'; Test-RequiredPath $ContentRoot 'directory' 'content addon root'; $addonInfo = Join-Path $GameRoot 'addoninfo.txt'; Test-RequiredPath $addonInfo 'file' 'addon metadata'; Test-RequiredPath (Join-Path $GameRoot 'scripts/vscripts/addon_game_mode.lua') 'file' 'lua entry'; Test-RequiredPath (Join-Path $GameRoot ('resource/addon_' + $AddonName + '_english.txt')) 'file' 'localization file'; Test-RequiredPath (Join-Path $ContentRoot 'maps') 'directory' 'content maps directory'; Test-RequiredPath (Join-Path $GameRoot 'scripts/npc/herolist.txt') 'file' 'hero list'; Test-RequiredPath (Join-Path $GameRoot 'scripts/npc/npc_heroes_custom.txt') 'file' 'hero data'; Test-RequiredPath (Join-Path $GameRoot 'scripts/npc/npc_units_custom.txt') 'file' 'unit support file'; Test-RequiredPath (Join-Path $GameRoot 'scripts/npc/npc_abilities_custom.txt') 'file' 'ability support file'; $metadataIdentity = 'game/dota_addons/' + $AddonName + '/addoninfo.txt'; $metadataFiles = @($Files | Where-Object { $_.identity -ceq $metadataIdentity }); $metadataFile = $(if ($metadataFiles.Count -eq 1) { $metadataFiles[0] } else { $null }); if ($null -ne $metadataFile -and (Test-Path -LiteralPath $addonInfo)) { try { Assert-SafeSourceFile $metadataFile; $metadataText = [IO.File]::ReadAllText($addonInfo, [Text.UTF8Encoding]::new($false, $true)); foreach ($key in $ReleaseMetadataKeys) { $match = [regex]::Match($metadataText, '\"' + [regex]::Escape($key) + '\"\\s+\"([^\"]*)\"', [Text.RegularExpressions.RegexOptions]::IgnoreCase); if (-not $match.Success) { Add-Blocker 'METADATA_MISSING' 'metadata' '' $key } elseif (@('', 'changeme', 'change me', 'placeholder', 'tbd', 'todo', 'unknown', 'your name') -contains $match.Groups[1].Value.Trim().ToLowerInvariant()) { Add-Blocker 'METADATA_PLACEHOLDER' 'metadata' '' $key } } } catch { Add-Blocker 'REQUIRED_TEXT_UNREADABLE' 'unreadable-required-text' 'game/dota_addons/' + $AddonName + '/addoninfo.txt' } }; $textExtensions = @('.cfg', '.css', '.ini', '.js', '.json', '.kv', '.lua', '.md', '.ps1', '.ts', '.tsx', '.txt', '.vdf', '.xml', '.yaml', '.yml'); $requiredText = @('game/dota_addons/' + $AddonName + '/addoninfo.txt', 'game/dota_addons/' + $AddonName + '/scripts/vscripts/addon_game_mode.lua', 'game/dota_addons/' + $AddonName + '/resource/addon_' + $AddonName + '_english.txt', 'game/dota_addons/' + $AddonName + '/scripts/npc/herolist.txt', 'game/dota_addons/' + $AddonName + '/scripts/npc/npc_heroes_custom.txt', 'game/dota_addons/' + $AddonName + '/scripts/npc/npc_units_custom.txt', 'game/dota_addons/' + $AddonName + '/scripts/npc/npc_abilities_custom.txt'); foreach ($file in $Files) { Assert-SafeSourceFile $file; $extension = [IO.Path]::GetExtension($file.relative).ToLowerInvariant(); if ($textExtensions -notcontains $extension) { $result.scanCoverage.binary.paths += $file.identity; continue }; if ($file.bytes -gt $MaxSecretScanBytes) { $result.scanCoverage.oversized.paths += $file.identity; if ($requiredText -contains $file.identity) { Add-Blocker 'REQUIRED_TEXT_OVERSIZED' 'oversized-required-text' $file.identity }; continue }; try { $content = [IO.File]::ReadAllText($file.source, [Text.UTF8Encoding]::new($false, $true)); $result.scanCoverage.text.paths += $file.identity; foreach ($rule in $SensitiveMaterialRules) { $options = $(if ($rule.ignoreCase) { [Text.RegularExpressions.RegexOptions]::IgnoreCase } else { [Text.RegularExpressions.RegexOptions]::None }); if ([regex]::IsMatch($content, $rule.pattern, $options)) { Add-Blocker 'SENSITIVE_MATERIAL' $rule.category $file.identity } } } catch { $result.scanCoverage.unreadable.paths += $file.identity; if ($requiredText -contains $file.identity) { Add-Blocker 'REQUIRED_TEXT_UNREADABLE' 'unreadable-required-text' $file.identity } } }; foreach ($name in @('text', 'binary', 'unreadable', 'oversized')) { $paths = @($result.scanCoverage[$name].paths); [Array]::Sort($paths, [StringComparer]::Ordinal); $result.scanCoverage[$name].paths = $paths; $result.scanCoverage[$name].count = $paths.Count }; $result.scanCoverage.totalFileCount = $Files.Count }",
        "function New-CandidateRoot([string]$DotaRoot, [string]$GameRoot, [string]$ContentRoot, [object]$IsolationLease) { $parent = [IO.Path]::GetTempPath(); if (-not (Test-IsolationLease $IsolationLease)) { Stop-ReleaseCandidate 'TEMP_PARENT_NOT_ISOLATED' 'isolation' }; Assert-NoReparseAncestry $parent 'TEMP_PARENT_NOT_ISOLATED'; if (-not (Test-PathsDisjoint $parent $DotaRoot) -or -not (Test-PathsDisjoint $parent $GameRoot) -or -not (Test-PathsDisjoint $parent $ContentRoot)) { Stop-ReleaseCandidate 'TEMP_PARENT_NOT_ISOLATED' 'isolation' }; $leaf = 'dota-workshop-rc-' + [Guid]::NewGuid().ToString('N'); $path = Join-Path $parent $leaf; if (-not (Test-PathsDisjoint $path $DotaRoot) -or -not (Test-PathsDisjoint $path $GameRoot) -or -not (Test-PathsDisjoint $path $ContentRoot)) { Stop-ReleaseCandidate 'CANDIDATE_ROOT_NOT_ISOLATED' 'isolation' }; [IO.Directory]::CreateDirectory($path) | Out-Null; $script:candidateRoot = $path; $script:candidateCreated = $true; return [ordered]@{ path = $path; identity = Get-WindowsFileIdentity $path } }",
        "function Test-OwnedCandidateRoot([string]$CandidateRoot, [string]$Identity, [bool]$RequireEmpty) { try { $parent = [IO.Path]::GetTempPath(); $item = Get-Item -LiteralPath $CandidateRoot -Force; $observedIdentity = Get-WindowsFileIdentity $CandidateRoot $false; return $null -ne $observedIdentity -and $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0 -and (Test-ContainedPath $parent $CandidateRoot) -and $observedIdentity.Equals($Identity, [StringComparison]::Ordinal) -and (-not $RequireEmpty -or @(Get-ChildItem -LiteralPath $CandidateRoot -Force).Count -eq 0) } catch { return $false } }",
        "function Assert-OwnedCandidateRoot([string]$CandidateRoot, [string]$Identity) { if (-not (Test-OwnedCandidateRoot $CandidateRoot $Identity $true)) { Stop-ReleaseCandidate 'CANDIDATE_ROOT_NOT_ISOLATED' 'isolation' } }",
        "function Assert-CandidateRoot([string]$CandidateRoot, [string]$Identity) { Assert-OwnedCandidateRoot $CandidateRoot $Identity }",
        "function Assert-SourceStable([object[]]$Files, [Collections.IDictionary]$Before) { foreach ($file in $Files) { Assert-SafeSourceFile $file; $afterBytes = [long](Get-Item -LiteralPath $file.source -Force).Length; $afterHash = Get-FileSha256 $file.source; if ($afterBytes -ne $Before[$file.identity].bytes -or $afterHash -ne $Before[$file.identity].sha256) { Stop-ReleaseCandidate 'SOURCE_CHANGED_DURING_ASSEMBLY' 'source-integrity' $file.identity } } }",
        "function Get-FinalCandidateEntries([object[]]$Files, [string]$CandidateRoot, [Collections.IDictionary]$Before) { $entries = @(); foreach ($file in $Files) { $candidate = Join-Path $CandidateRoot $file.identity; if (-not (Test-ContainedPath $CandidateRoot $candidate)) { Stop-ReleaseCandidate 'CANDIDATE_TREE_UNEXPECTED' 'candidate-topology' $file.identity }; $item = Get-Item -LiteralPath $candidate -Force; if (-not ($item -is [IO.FileInfo]) -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-ReleaseCandidate 'RELEASE_CANDIDATE_INTEGRITY_MISMATCH' 'candidate-integrity' $file.identity }; $candidateBytes = [long]$item.Length; $candidateHash = Get-FileSha256 $candidate; if ($candidateBytes -ne $Before[$file.identity].bytes -or $candidateHash -ne $Before[$file.identity].sha256) { Stop-ReleaseCandidate 'RELEASE_CANDIDATE_INTEGRITY_MISMATCH' 'candidate-integrity' $file.identity }; $entries += [ordered]@{ schemaVersion = $SchemaVersion; root = $file.root; path = $file.identity; bytes = $candidateBytes; sha256 = $candidateHash } }; return @($entries) }",
        "function Assert-CandidateLedger([object[]]$Files, [object[]]$Entries) { if ($Files.Count -ne $Entries.Count) { Stop-ReleaseCandidate 'CANDIDATE_TREE_MISMATCH' 'candidate-ledger' }; for ($index = 0; $index -lt $Files.Count; $index += 1) { if ($Files[$index].identity -ne $Entries[$index].path) { Stop-ReleaseCandidate 'CANDIDATE_LEDGER_MISSING' 'candidate-ledger' $Files[$index].identity } } }",
        "function Assert-CandidateTopology([object[]]$Directories, [string]$CandidateRoot) { foreach ($directory in $Directories) { $candidate = Join-Path $CandidateRoot $directory.identity; if (-not (Test-Path -LiteralPath $candidate -PathType Container)) { Stop-ReleaseCandidate 'CANDIDATE_TREE_MISSING' 'candidate-topology' $directory.identity } }; $expectedSet = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal); foreach ($identity in @('game', 'game/dota_addons', 'game/dota_addons/' + $AddonName, 'content', 'content/dota_addons', 'content/dota_addons/' + $AddonName) + $Directories.identity + $script:allFiles.identity) { $expectedSet.Add($identity) | Out-Null }; $expected = @($expectedSet); [Array]::Sort($expected, [StringComparer]::Ordinal); $observed = @(); foreach ($item in @(Get-ChildItem -LiteralPath $CandidateRoot -Recurse -Force)) { $observed += (Get-SafeRelativePath $CandidateRoot $item.FullName).Replace('\\', '/') }; [Array]::Sort($observed, [StringComparer]::Ordinal); if ((ConvertTo-Json -InputObject $expected -Compress) -ne (ConvertTo-Json -InputObject $observed -Compress)) { Stop-ReleaseCandidate 'CANDIDATE_TREE_UNEXPECTED' 'candidate-topology' } }",
        "function Get-CanonicalManifestDigest([object[]]$Entries) { $rows = @(); foreach ($entry in $Entries) { $rows += ,@($entry.root, $entry.path, [long]$entry.bytes, $entry.sha256) }; $payload = [object[]]::new(2); $payload[0] = $SchemaVersion; $payload[1] = [object[]]$rows; return Get-TextSha256 (ConvertTo-Json -InputObject $payload -Depth 4 -Compress) }",
        `$result = [ordered]@{ schemaVersion = $SchemaVersion; operation = [ordered]@{ status = 'not-reached' }; artifactValidation = [ordered]@{ status = $PrecreationArtifactStatus }; blockers = @(); cleanup = [ordered]@{ schemaVersion = $SchemaVersion; attempted = $false; attempts = 0; status = 'not-reached'; verified = $false }; paths = [ordered]@{ gameAddon = "game/dota_addons/$AddonName"; contentAddon = "content/dota_addons/$AddonName" }; execution = [ordered]@{ kind = 'remote'; outcome = 'completed'; exitCode = 0 }; warnings = @($ContractEvidenceWarning); commands = @(); logs = @(); boundaries = [ordered]@{ ${boundaries} }; scanCoverage = [ordered]@{ schemaVersion = $SchemaVersion; totalFileCount = 0; text = [ordered]@{ count = 0; paths = @() }; binary = [ordered]@{ count = 0; paths = @() }; unreadable = [ordered]@{ count = 0; paths = @() }; oversized = [ordered]@{ count = 0; paths = @() } } }`,
        "$candidateRoot = $null",
        "$candidateIdentity = $null",
        "$candidateCreated = $false",
        "$isolationLease = $null",
        "try {",
        "  if ((Get-TextSha256 $CanonicalVectorJson) -ne $CanonicalVectorSha256 -or (Get-CanonicalManifestDigest $CanonicalVectorEntries) -ne $CanonicalVectorSha256) { Stop-ReleaseCandidate 'CANDIDATE_MANIFEST_PROJECTION_FAILED' 'manifest' }",
        "  if ($AddonName -notmatch '^[a-z][a-z0-9_]{0,63}$') { Add-Blocker 'INVALID_ADDON_NAME' 'input' }",
        "  $dotaRoot = [IO.Path]::GetFullPath($DotaRootInput)",
        "  $gameAddonRoot = Join-Path $dotaRoot ('game/dota_addons/' + $AddonName)",
        "  $contentAddonRoot = Join-Path $dotaRoot ('content/dota_addons/' + $AddonName)",
        "  if (-not (Test-ContainedPath $dotaRoot $gameAddonRoot)) { Add-Blocker 'GAME_ADDON_ROOT_OUTSIDE_DOTA_ROOT' 'isolation' }",
        "  if (-not (Test-ContainedPath $dotaRoot $contentAddonRoot)) { Add-Blocker 'CONTENT_ADDON_ROOT_OUTSIDE_DOTA_ROOT' 'isolation' }",
        "  Test-RequiredPath $gameAddonRoot 'directory' 'game addon root'",
        "  Test-RequiredPath $contentAddonRoot 'directory' 'content addon root'",
        "  if ($result.blockers.Count -eq 0) { Assert-SafeSourceRoot $dotaRoot $gameAddonRoot; Assert-SafeSourceRoot $dotaRoot $contentAddonRoot; Assert-SafeSourceTree 'game' $gameAddonRoot; Assert-SafeSourceTree 'content' $contentAddonRoot; $gameInventory = Get-SourceInventory 'game' $gameAddonRoot; $contentInventory = Get-SourceInventory 'content' $contentAddonRoot; $gameTopology = Get-InventoryTopology $gameInventory; $contentTopology = Get-InventoryTopology $contentInventory; $script:allFiles = @($gameInventory.files + $contentInventory.files); $allDirectories = @($gameInventory.directories + $contentInventory.directories); [Array]::Sort($script:allFiles, [Collections.Generic.Comparer[object]]::Create([Comparison[object]]{ param($left, $right) [StringComparer]::Ordinal.Compare($left.identity, $right.identity) })); Test-ReleaseReadiness $gameAddonRoot $contentAddonRoot $script:allFiles; $tempParent = [IO.Path]::GetTempPath(); $isolationLease = New-IsolationLease $tempParent $dotaRoot $gameAddonRoot $contentAddonRoot }",
        "  if ($result.blockers.Count -eq 0) {",
        "    $created = New-CandidateRoot $dotaRoot $gameAddonRoot $contentAddonRoot $isolationLease; $candidateIdentity = $created.identity; Assert-CandidateRoot $candidateRoot $candidateIdentity",
        "    $before = @{}; foreach ($file in $script:allFiles) { Assert-SafeSourceFile $file; $before[$file.identity] = [ordered]@{ bytes = [long](Get-Item -LiteralPath $file.source -Force).Length; sha256 = Get-FileSha256 $file.source } }",
        "    foreach ($directory in $allDirectories) { [IO.Directory]::CreateDirectory((Join-Path $candidateRoot $directory.identity)) | Out-Null }",
        "    foreach ($file in $script:allFiles) { Assert-SafeSourceFile $file; $destination = Join-Path $candidateRoot $file.identity; [IO.Directory]::CreateDirectory((Split-Path -Parent $destination)) | Out-Null; Copy-FileStreamed $file.source $destination }",
        "    Assert-SourceStable $script:allFiles $before; Assert-SourceTopologyStable $gameAddonRoot $contentAddonRoot $gameTopology $contentTopology; Assert-CandidateTopology $allDirectories $candidateRoot; $finalEntries = Get-FinalCandidateEntries $script:allFiles $candidateRoot $before; Assert-CandidateLedger $script:allFiles $finalEntries; Assert-CandidateTopology $allDirectories $candidateRoot",
        "    $manifest = [ordered]@{ schemaVersion = $SchemaVersion; entries = @($finalEntries); combinedSha256 = Get-CanonicalManifestDigest $finalEntries }",
        "    $ledger = [ordered]@{ schemaVersion = $SchemaVersion; expectedFileCount = $script:allFiles.Count; observedFileCount = $finalEntries.Count; matchedFileCount = $finalEntries.Count }",
        "    $result.manifest = $manifest; $result.inclusionLedger = $ledger; $result.artifactValidation = [ordered]@{ status = 'passed'; manifest = $manifest; inclusionLedger = $ledger; scanCoverage = $result.scanCoverage }; $result.operation = [ordered]@{ status = 'completed' }",
        "  }",
        "} catch {",
        "  if ($result.blockers.Count -eq 0) { Add-Blocker 'REMOTE_LIFECYCLE_INTERNAL_FAILURE' 'remote-script' }",
        "  if ($result.artifactValidation.status -eq 'not-reached' -and $candidateCreated) { $result.artifactValidation = [ordered]@{ status = 'blocked'; blockers = @($result.blockers); scanCoverage = $result.scanCoverage } }",
        "} finally {",
        "  if ($candidateCreated) { if ($null -eq $candidateIdentity) { $result.cleanup = [ordered]@{ schemaVersion = $SchemaVersion; attempted = $false; attempts = 0; status = 'failed'; verified = $false; code = 'CANDIDATE_CLEANUP_IDENTITY_UNAVAILABLE' }; Add-Blocker 'CANDIDATE_CLEANUP_IDENTITY_UNAVAILABLE' 'removal' } else { $leaseValid = $false; try { $leaseValid = Test-IsolationLease $isolationLease } catch { $leaseValid = $false }; if ($leaseValid) { $result.cleanup = [ordered]@{ schemaVersion = $SchemaVersion; attempted = $true; attempts = 1; status = 'failed'; verified = $false; code = 'CANDIDATE_REMOVAL_FAILED'; identityMatched = $false; removed = $false; absent = $false }; $identityMatched = Test-OwnedCandidateRoot $candidateRoot $candidateIdentity $false; $result.cleanup.identityMatched = $identityMatched; if ($identityMatched) { try { Remove-Item -LiteralPath $candidateRoot -Recurse -Force -ErrorAction Stop; $result.cleanup.removed = $true } catch { $result.cleanup.removed = $false }; $result.cleanup.absent = -not (Test-Path -LiteralPath $candidateRoot); if ($result.cleanup.removed -and $result.cleanup.absent) { $result.cleanup.status = 'verified'; $result.cleanup.verified = $true; $result.cleanup.Remove('code') | Out-Null } elseif ($result.cleanup.removed) { $result.cleanup.code = 'CANDIDATE_ABSENCE_UNVERIFIED' } } else { $result.cleanup.code = 'CANDIDATE_IDENTITY_MISMATCH' } } else { $result.cleanup = [ordered]@{ schemaVersion = $SchemaVersion; attempted = $true; attempts = 1; status = 'failed'; verified = $false; code = 'CANDIDATE_CLEANUP_RESULT_INVALID' } }; if (-not $result.cleanup.verified) { Add-Blocker $result.cleanup.code 'removal' } } }",
        "}",
        "$result.ok = ($result.operation.status -eq 'completed' -and $result.artifactValidation.status -eq 'passed' -and $result.blockers.Count -eq 0 -and $result.cleanup.status -eq 'verified')",
        "[Console]::Out.Write(($result | ConvertTo-Json -Depth 20 -Compress))"
    ].join("\n");
}
function quotePowerShell(value) {
    return `'${value.replace(/'/g, "''")}'`;
}
